def read(p):return json.loads(Path(p).read_text(encoding='utf-8-sig'))
def write(p,x):
    with Path(p).open('x',encoding='utf-8') as f:json.dump(x,f,ensure_ascii=False,indent=2)
old=read(P/'INPUTS.json')['cases'];cases=[]
for phase,reps,ns in [('TRAIN',[20],[256,512]),('DEV',[21],[512]),('EVAL',[22,23],[1024])]:
    for rep in reps:
        for n in ns:
            for mix in [.5,.75]:
                for load in [.65,.85]:
                    src=next(c for c in old if c['phase']=='TRAIN' and c['n']==(256 if n==256 else 1024) and c['mix']==mix and c['nominal_load_ratio']==load)
                    c=copy.deepcopy(src);c.update(n=n,phase=phase,replicate=rep,model='CPU3',stream=871000000+rep*100000+len(cases)*107,id=f'{phase}_N{n}_C{mix}_U{load}_R{rep}_CPU3');c['requests']=c['requests'][:n];c['duration']=n/c['rate'];c['horizon_s']=35+c['duration']+90;c['dispatch_stop_s']=35+c['duration']+45;c['censor_s']=35+c['duration']+60;cases.append(c)
c=copy.deepcopy(cases[0]);c.update(id='P0_N64_C0.5_U0.65_R24_CPU3',phase='P0',replicate=24,n=64,stream=879000000);c['requests']=c['requests'][:64];cases.append(c)
